# Generated by manage.py generate_test_cases.
from datetime import timedelta
from functools import partial
from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.document_signing import SignatureLayoutField
from bloomerp.models.document_signing.signature_request import SignatureRequest
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .support import SigningFixturesMixin


class TestSignatureRequestModel(SigningFixturesMixin, BloomerpModelTestCase):
    """Cover dispatch prerequisites, independent snapshots, and retained completion."""

    model = SignatureRequest

    def sent_args(self, **overrides: Any) -> dict[str, Any]:
        """Build coherent dispatch metadata for a prepared draft."""
        return {
            "status": SignatureRequest.Status.SENT,
            "sent_at": self.now,
            **overrides,
        }

    def completion_args(self, **overrides: Any) -> dict[str, Any]:
        """Build the metadata required to retain a completed PDF separately."""
        return {
            "status": SignatureRequest.Status.COMPLETED,
            "signed_file": self.output,
            "signed_sha256": self.digest,
            "completed_at": self.now + timedelta(seconds=4),
            **overrides,
        }

    def only_recipient(self, request: SignatureRequest) -> None:
        """Prepare an intentionally incomplete request without signer placements."""
        self.create_recipient(request)

    def prepare_completion(self, request: SignatureRequest) -> None:
        """Prepare all signer responses before retaining the finished PDF."""
        self.populate_and_dispatch(request)
        self.sign_recipient(request.recipients.get())

    def edit_source_layout(self, request: SignatureRequest) -> None:
        """Change a reusable layout after explicitly copying its request snapshots."""
        self.populate_request(request)
        SignatureLayoutField.objects.create(**self.layout_field_args())
        self.layout.name = "Changed layout"
        self.layout.revision = 2
        self.layout.save()
        self.role.label = "Changed role"
        self.role.save()
        placement = self.layout.fields.get()
        placement.x = "0.5"
        placement.save()

    def validate_snapshot(self, request: SignatureRequest) -> bool:
        """Verify that editing reusable configuration leaves request facts intact."""
        return (
            request.source_layout_name == "Two-party agreement"
            and request.source_layout_revision == 1
            and request.fields.get().x == 0
            and request.recipients.get().role_label == "party_a"
        )

    def get_test_scenarios(self) -> list[ModelScenario[SignatureRequest]]:
        """Exercise valid lifecycle progression and forbidden changes to sent PDFs."""
        return [
            ModelScenario(
                name="Create a standalone draft and update its title",
                create_args=self.request_args,
                update_args={"title": "Revised draft"},
            ),
            ModelScenario(
                name="Reject folders as original documents",
                create_args=partial(self.request_args, original_file=self.folder),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Reject unsupported qualified-signature claims",
                create_args=partial(self.request_args, signature_level="qualified"),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Require requests to start as drafts",
                create_args=partial(
                    self.request_args, status=SignatureRequest.Status.SENT
                ),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Require recipients before dispatch",
                create_args=self.request_args,
                update_args=self.sent_args,
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Require placements for each recipient",
                create_args=self.request_args,
                post_create=self.only_recipient,
                update_args=self.sent_args,
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Require an original document digest before dispatch",
                create_args=self.request_args,
                post_create=self.populate_request,
                update_args=partial(self.sent_args, original_sha256=""),
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Freeze a dispatched original",
                create_args=self.request_args,
                post_create=self.populate_and_dispatch,
                update_args={"original_file": self.output},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Retain dispatched requests",
                create_args=self.request_args,
                post_create=self.populate_and_dispatch,
                expected_exceptions=[ExpectedModelException("delete", ValidationError)],
            ),
            ModelScenario(
                name="Complete a document after every recipient signs",
                create_args=self.request_args,
                post_create=self.prepare_completion,
                update_args=self.completion_args,
            ),
            ModelScenario(
                name="Reject completion while signers remain pending",
                create_args=self.request_args,
                post_create=self.populate_and_dispatch,
                update_args=self.completion_args,
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Retain the original separately from completed output",
                create_args=self.request_args,
                post_create=self.prepare_completion,
                update_args=partial(self.completion_args, signed_file=self.original),
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Keep copied placements and roles independent of reusable layout edits",
                create_args=partial(
                    self.request_args,
                    source_layout=self.layout,
                    source_layout_name=self.layout.name,
                    source_layout_revision=self.layout.revision,
                ),
                post_create=self.edit_source_layout,
                create_validators=self.validate_snapshot,
            ),
        ]

    def test_bulk_writes_cannot_bypass_validation(self) -> None:
        """Reject bulk changes and inserts rather than bypassing lifecycle checks."""
        with self.assertRaises(TypeError):
            SignatureRequest.objects.filter(pk=self.request.pk).update(
                status="completed"
            )
        with self.assertRaises(TypeError):
            SignatureRequest.objects.bulk_create(
                [SignatureRequest(**self.request_args())]
            )
        with self.assertRaises(TypeError):
            SignatureRequest.objects.bulk_update([self.request], ["title"])

    def test_queryset_deletion_retains_sent_requests(self) -> None:
        """Apply request retention even when deletion starts from a queryset."""
        self.dispatch_request(self.request)
        with self.assertRaises(ValidationError):
            SignatureRequest.objects.filter(pk=self.request.pk).delete()
        self.assertTrue(SignatureRequest.objects.filter(pk=self.request.pk).exists())

    def test_legacy_import_resolves_the_registered_model(self) -> None:
        """Keep callers of the earlier placeholder path on the real model."""
        from bloomerp.models.communication.signature_request import (
            SignatureRequest as LegacyRequest,
        )

        self.assertIs(LegacyRequest, SignatureRequest)

    def test_models_do_not_generate_public_signing_endpoints(self) -> None:
        """Keep this persistence foundation internal until its workflow is implemented."""
        self.assertTrue(SignatureRequest.bloomerp_config.is_internal)
        self.assertFalse(
            SignatureRequest.bloomerp_config.should_enable_api_auto_generation()
        )
